<?php
$e = static fn($value): string => htmlspecialchars((string) ($value ?? ''), ENT_QUOTES, 'UTF-8');
$table = $table ?? [];
?>
<div class="container-fluid py-4"><div class="d-flex justify-content-between align-items-center mb-4"><h1 class="h3 mb-0"><?= $e($title ?? 'Table') ?></h1><a class="btn btn-outline-secondary" href="<?= BASE_URL ?>/tables">Back</a></div><?php if (!empty($error)): ?><div class="alert alert-danger"><?= $e($error) ?></div><?php endif; ?><form method="POST" action="<?= $e($action) ?>" class="card border-0 shadow-sm"><div class="card-body"><div class="row g-3"><div class="col-md-6"><label class="form-label">Table number</label><input class="form-control" name="table_number" required value="<?= $e($table['table_number'] ?? '') ?>"></div><div class="col-md-6"><label class="form-label">Capacity</label><input class="form-control" type="number" min="1" max="99" name="capacity" value="<?= $e($table['capacity'] ?? 2) ?>"></div><?php if (!empty($table)): ?><div class="col-md-6"><label class="form-label">Status</label><select class="form-select" name="status"><?php foreach (['available', 'occupied', 'reserved', 'inactive'] as $status): ?><option value="<?= $status ?>" <?= ($table['status'] ?? '') === $status ? 'selected' : '' ?>><?= ucfirst($status) ?></option><?php endforeach; ?></select></div><?php endif; ?><div class="col-12 text-end"><button class="btn btn-primary">Save table</button></div></div></div></form></div>
